  (4, '2026-06-13', 'Kota Lama', 'Jl. Cempaka',             'Kecelakaan', 'Motor kurir tergelincir di depan galeri. Tidak ada korban luka.'),
  (5, '2026-06-14', 'Kota Lama', 'Galeri Sekar Arum',       'Lain-lain',  'Pameran tetap dibuka tanpa karya utama.');
